-- ── hand-amended: the header CHECKs (migration SQL only) ──────────────────
-- Every nullable vocabulary says IS NOT NULL before IN (guide §3). Postgres
-- evaluates a row's CHECKs in NAME order; the probes below are built so each
-- refused shape violates only its target (or targets that sort after it).
ALTER TABLE "client_returns" ADD CONSTRAINT "client_returns_status_check" CHECK (
	"status" IN ('draft', 'picked', 'dispatched', 'cancelled')
);--> statement-breakpoint
ALTER TABLE "client_returns" ADD CONSTRAINT "client_returns_consignee_address_kind_check" CHECK (
	"consignee_address_kind" IN ('return', 'registered')
);--> statement-breakpoint
ALTER TABLE "client_returns" ADD CONSTRAINT "client_returns_brand_document_type_check" CHECK (
	"brand_document_type" IS NULL OR ("brand_document_type" IS NOT NULL AND "brand_document_type" IN ('challan', 'invoice'))
);--> statement-breakpoint
-- The pick (2-8b A1 verbatim): a draft carries no picker; a picked or
-- dispatched RTC carries all three; a cancelled one all three or none.
ALTER TABLE "client_returns" ADD CONSTRAINT "client_returns_picked_pairing" CHECK (
	("status" <> 'draft' OR ("picked_by" IS NULL AND "picked_at" IS NULL AND "picked_device_id" IS NULL))
	AND ("status" NOT IN ('picked', 'dispatched') OR ("picked_by" IS NOT NULL AND "picked_at" IS NOT NULL AND "picked_device_id" IS NOT NULL))
	AND ("picked_by" IS NULL) = ("picked_at" IS NULL)
	AND ("picked_at" IS NULL) = ("picked_device_id" IS NULL)
);--> statement-breakpoint
-- The dispatch: a dispatched RTC carries the dispatcher, the instant, the
-- brand document and the package count; no other status carries any
-- dispatch column at all — `consignee_gstin` and `declared_value_paise`
-- included (A12).
ALTER TABLE "client_returns" ADD CONSTRAINT "client_returns_dispatch_pairing" CHECK (
	("status" = 'dispatched'
		AND "dispatched_by" IS NOT NULL AND "dispatched_at" IS NOT NULL
		AND "brand_document_type" IS NOT NULL AND "brand_document_number" IS NOT NULL
		AND "brand_document_date" IS NOT NULL AND "package_count" IS NOT NULL)
	OR ("status" <> 'dispatched'
		AND "dispatched_by" IS NULL AND "dispatched_at" IS NULL
		AND "brand_document_type" IS NULL AND "brand_document_number" IS NULL
		AND "brand_document_date" IS NULL AND "package_count" IS NULL
		AND "eway_bill_number" IS NULL AND "eway_bill_date" IS NULL AND "eway_valid_until" IS NULL
		AND "consignor_gstin" IS NULL AND "consignee_gstin" IS NULL AND "declared_value_paise" IS NULL
		AND "transporter_id" IS NULL AND "transporter_snapshot" IS NULL
		AND "carrier_name" IS NULL AND "tracking_ref" IS NULL AND "vehicle_number" IS NULL
		AND "warehouse_snapshot" IS NULL)
);--> statement-breakpoint
ALTER TABLE "client_returns" ADD CONSTRAINT "client_returns_transporter_pairing" CHECK (
	("transporter_id" IS NULL) = ("transporter_snapshot" IS NULL)
);--> statement-breakpoint
ALTER TABLE "client_returns" ADD CONSTRAINT "client_returns_cancel_pairing" CHECK (
	("status" = 'cancelled') = ("cancelled_by" IS NOT NULL AND "cancelled_at" IS NOT NULL AND "cancel_reason" IS NOT NULL)
	AND ("cancelled_by" IS NULL) = ("cancelled_at" IS NULL)
	AND ("cancelled_at" IS NULL) = ("cancel_reason" IS NULL)
);--> statement-breakpoint
-- Decision 10 (2-8b decision 9): a dispatched RTC names who carries the
-- goods — a transporter partner, a carrier name or a vehicle.
ALTER TABLE "client_returns" ADD CONSTRAINT "client_returns_carrier_identity" CHECK (
	"status" <> 'dispatched' OR "transporter_id" IS NOT NULL OR "carrier_name" IS NOT NULL OR "vehicle_number" IS NOT NULL
);--> statement-breakpoint
-- The capture formats (`shared/primitives/consignment-capture.ts` and the
-- command are the named refusals; these are the backstop).
ALTER TABLE "client_returns" ADD CONSTRAINT "client_returns_capture_format" CHECK (
	("brand_document_number" IS NULL OR char_length("brand_document_number") BETWEEN 1 AND 40)
	AND ("carrier_name" IS NULL OR char_length("carrier_name") BETWEEN 1 AND 100)
	AND ("tracking_ref" IS NULL OR char_length("tracking_ref") BETWEEN 1 AND 50)
	AND ("vehicle_number" IS NULL OR "vehicle_number" ~ '^[A-Z0-9]{4,15}$')
	AND ("consignor_gstin" IS NULL OR "consignor_gstin" ~ '^[0-9]{2}[A-Z0-9]{13}$')
	AND ("consignee_gstin" IS NULL OR "consignee_gstin" ~ '^[0-9]{2}[A-Z0-9]{13}$')
	AND ("declared_value_paise" IS NULL OR "declared_value_paise" BETWEEN 0 AND 1000000000000)
	AND ("eway_bill_number" IS NULL OR "eway_bill_number" ~ '^[0-9]{12}$')
	AND ("package_count" IS NULL OR "package_count" BETWEEN 1 AND 9999)
);--> statement-breakpoint
-- A12 — an e-way bill number carries its date; the date and the validity
-- are NULL without a number; the validity runs from the date.
ALTER TABLE "client_returns" ADD CONSTRAINT "client_returns_eway_pairing" CHECK (
	("eway_bill_number" IS NULL) = ("eway_bill_date" IS NULL)
	AND ("eway_valid_until" IS NULL OR ("eway_bill_date" IS NOT NULL AND "eway_valid_until" >= "eway_bill_date"))
);--> statement-breakpoint
ALTER TABLE "client_returns" ADD CONSTRAINT "client_returns_note_length" CHECK (
	("note" IS NULL OR char_length("note") BETWEEN 1 AND 500)
	AND ("cancel_reason" IS NULL OR char_length("cancel_reason") BETWEEN 1 AND 500)
);--> statement-breakpoint
