-- neither, and no serial (DAMAGED holds no serials — decision 12).
ALTER TABLE "client_return_lines" ADD CONSTRAINT "client_return_lines_source_shape" CHECK (
	("source" <> 'returns' OR ("return_receipt_line_id" IS NOT NULL AND "rma_id" IS NOT NULL))
