ALTER TABLE "client_return_lines" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "client_returns_tenant_isolation" ON "client_returns"
	USING (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR "client_id" = NULLIF(current_setting('app.client_id', true), '')::uuid
		)
	)
	WITH CHECK (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR "client_id" = NULLIF(current_setting('app.client_id', true), '')::uuid
		)
	);--> statement-breakpoint
CREATE POLICY "client_return_lines_tenant_isolation" ON "client_return_lines"
	USING (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR EXISTS (
				SELECT 1 FROM "client_returns" r
				WHERE r."tenant_id" = "client_return_lines"."tenant_id" AND r."id" = "client_return_lines"."client_return_id"
			)
		)
	)
	WITH CHECK (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR EXISTS (
				SELECT 1 FROM "client_returns" r
				WHERE r."tenant_id" = "client_return_lines"."tenant_id" AND r."id" = "client_return_lines"."client_return_id"
			)
		)
	);--> statement-breakpoint
-- ── the post-migration assertion (the 0064/0105 model) ────────────────────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK that refused everything fails the
-- migration; each refused shape runs in its own subtransaction — a valid
-- base row, then the one change under test — and must be refused BY ITS
-- NAMED CONSTRAINT (guide §3, CHECKs in name order).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	w uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	v uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	d uuid := gen_random_uuid();
	l uuid := gen_random_uuid();
	r uuid;
	refused_by text;
	expected text;
	probe text;
	base text;
BEGIN
	IF NOT (SELECT relrowsecurity FROM pg_class WHERE relname = 'client_returns')
		OR NOT (SELECT relrowsecurity FROM pg_class WHERE relname = 'client_return_lines') THEN
		RAISE EXCEPTION 'migration 0113: row level security is not enabled on the new tables.';
	END IF;
	-- (1) accepted shapes: a draft, a picked, a dispatched (with an e-way
	-- bill, a transporter, a vehicle, both GSTINs and a declared value), a
	-- dispatched naming only a transporter and one naming only a vehicle, a
	-- draft cancelled, a picked RTC cancelled, and lines — a returns line, a
	-- serial line picked whole and picked 0, a damaged line with and without
	-- a batch, picked short.
	BEGIN
		r := gen_random_uuid();
		INSERT INTO "client_returns" ("id","tenant_id","client_id","warehouse_id","code","status","client_snapshot","consignee_address_kind","consignee_address","note","created_by")
		VALUES (r, t, c, w, 'RTC-P001', 'draft', '{}', 'return', '{}', 'probe', u);
		INSERT INTO "client_return_lines" ("id","tenant_id","client_return_id","line_no","source","sku_id","batch_id","serial_id","return_receipt_line_id","rma_id","qty","picked_qty","reason_code","item_snapshot")
		VALUES (gen_random_uuid(), t, r, 1, 'returns', c, NULL, NULL, l, v, 1, NULL, 'client-instruction', '{}'),
		       (gen_random_uuid(), t, r, 2, 'returns', c, d, u, gen_random_uuid(), v, 1000, NULL, 'damaged', '{}'),
		       (gen_random_uuid(), t, r, 3, 'damaged', c, NULL, NULL, NULL, NULL, 6000, NULL, 'other', '{}'),
		       (gen_random_uuid(), t, r, 4, 'damaged', c, d, NULL, NULL, NULL, 4000, NULL, 'expired', '{}');
		INSERT INTO "client_returns" ("id","tenant_id","client_id","warehouse_id","code","status","client_snapshot","consignee_address_kind","consignee_address","created_by","picked_by","picked_at","picked_device_id")
		VALUES (gen_random_uuid(), t, c, w, 'RTC-P002', 'picked', '{}', 'registered', '{}', u, u, now(), d);
		r := gen_random_uuid();
		INSERT INTO "client_returns" ("id","tenant_id","client_id","warehouse_id","code","status","client_snapshot","consignee_address_kind","consignee_address","created_by","picked_by","picked_at","picked_device_id",
			"dispatched_by","dispatched_at","brand_document_type","brand_document_number","brand_document_date","consignor_gstin","consignee_gstin","declared_value_paise","eway_bill_number","eway_bill_date","eway_valid_until",
			"transporter_id","transporter_snapshot","carrier_name","tracking_ref","vehicle_number","package_count","warehouse_snapshot")
		VALUES (r, t, c, w, 'RTC-P003', 'dispatched', '{}', 'return', '{}', u, u, now(), d,
			u, now(), 'invoice', 'INV-77', current_date, '29ABCDE1234F1Z5', '27ABCDE1234F1Z5', 1000000000000, '123456789012', current_date, current_date + 1,
			v, '{}', 'BlueDart', 'AWB1234', 'KA01AB1234', 9999, '{}');
		INSERT INTO "client_return_lines" ("id","tenant_id","client_return_id","line_no","source","sku_id","batch_id","serial_id","return_receipt_line_id","rma_id","qty","picked_qty","reason_code","item_snapshot")
		VALUES (gen_random_uuid(), t, r, 1, 'returns', c, NULL, u, l, v, 1000, 1000, 'client-instruction', '{}'),
		       (gen_random_uuid(), t, r, 2, 'returns', c, NULL, d, gen_random_uuid(), v, 1000, 0, 'client-instruction', '{}'),
		       (gen_random_uuid(), t, r, 200, 'damaged', c, NULL, NULL, NULL, NULL, 2000, 500, 'damaged', '{}');
		-- The carrier identity: a transporter alone, and a vehicle alone, each suffice.
		INSERT INTO "client_returns" ("id","tenant_id","client_id","warehouse_id","code","status","client_snapshot","consignee_address_kind","consignee_address","created_by","picked_by","picked_at","picked_device_id",
			"dispatched_by","dispatched_at","brand_document_type","brand_document_number","brand_document_date","transporter_id","transporter_snapshot","package_count","warehouse_snapshot")
		VALUES (gen_random_uuid(), t, c, w, 'RTC-P006', 'dispatched', '{}', 'return', '{}', u, u, now(), d,
			u, now(), 'challan', 'CH-6', current_date, v, '{}', 1, '{}');
		INSERT INTO "client_returns" ("id","tenant_id","client_id","warehouse_id","code","status","client_snapshot","consignee_address_kind","consignee_address","created_by","picked_by","picked_at","picked_device_id",
			"dispatched_by","dispatched_at","brand_document_type","brand_document_number","brand_document_date","vehicle_number","package_count","warehouse_snapshot")
		VALUES (gen_random_uuid(), t, c, w, 'RTC-P007', 'dispatched', '{}', 'return', '{}', u, u, now(), d,
			u, now(), 'challan', 'CH-7', current_date, 'KA01AB1234', 1, '{}');
		INSERT INTO "client_returns" ("id","tenant_id","client_id","warehouse_id","code","status","client_snapshot","consignee_address_kind","consignee_address","created_by","cancelled_by","cancelled_at","cancel_reason")
		VALUES (gen_random_uuid(), t, c, w, 'RTC-P004', 'cancelled', '{}', 'return', '{}', u, u, now(), 'cancel a draft');
		INSERT INTO "client_returns" ("id","tenant_id","client_id","warehouse_id","code","status","client_snapshot","consignee_address_kind","consignee_address","created_by","picked_by","picked_at","picked_device_id","cancelled_by","cancelled_at","cancel_reason")
		VALUES (gen_random_uuid(), t, c, w, 'RTC-P005', 'cancelled', '{}', 'registered', '{}', u, u, now(), d, u, now(), 'cancel a picked RTC');
		RAISE EXCEPTION USING ERRCODE = 'P0113', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0113: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0113' THEN
			NULL;
	END;
	-- (2) refused shapes: a base row of the named status, then one change.
	FOREACH probe IN ARRAY ARRAY[
		'unknown status', 'unknown address kind', 'unknown brand document type',
		'draft with a picker', 'picked without a device', 'cancelled with half a picker',
		'dispatched without a package count', 'draft with a tracking ref', 'draft with a brand document',
		'draft with a consignee GSTIN', 'draft with a declared value',
		'transporter without its snapshot', 'cancelled without a reason', 'draft with a canceller',
		'dispatched with no carrier', 'zero packages', 'malformed e-way bill', 'lowercase vehicle',
		'e-way bill without a date', 'validity before the e-way date', 'overlong note',
		'malformed consignor GSTIN', 'malformed consignee GSTIN', 'negative declared value', 'declared value above the bound',
		'overlong brand document number', 'validity without an e-way bill', 'e-way date without a number',
		'overlong cancel reason', 'cancelled missing only its reason',
		'zero line qty', 'picked above the line', 'negative picked', 'unknown reason', 'line 0',
		'unknown source', 'returns line without its receipt line', 'returns line without its RMA',
		'damaged line with a receipt line', 'damaged line with a serial',
		'serial line above one unit', 'serial line picked half',
		'duplicate arm', 'duplicate receipt line', 'duplicate line number'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'unknown status' THEN 'client_returns_status_check'
			WHEN 'unknown address kind' THEN 'client_returns_consignee_address_kind_check'
			WHEN 'unknown brand document type' THEN 'client_returns_brand_document_type_check'
			WHEN 'draft with a picker' THEN 'client_returns_picked_pairing'
			WHEN 'picked without a device' THEN 'client_returns_picked_pairing'
			WHEN 'cancelled with half a picker' THEN 'client_returns_picked_pairing'
			WHEN 'dispatched without a package count' THEN 'client_returns_dispatch_pairing'
			WHEN 'draft with a tracking ref' THEN 'client_returns_dispatch_pairing'
			WHEN 'draft with a brand document' THEN 'client_returns_dispatch_pairing'
			WHEN 'draft with a consignee GSTIN' THEN 'client_returns_dispatch_pairing'
			WHEN 'draft with a declared value' THEN 'client_returns_dispatch_pairing'
			WHEN 'transporter without its snapshot' THEN 'client_returns_transporter_pairing'
			WHEN 'cancelled without a reason' THEN 'client_returns_cancel_pairing'
			WHEN 'draft with a canceller' THEN 'client_returns_cancel_pairing'
			WHEN 'dispatched with no carrier' THEN 'client_returns_carrier_identity'
			WHEN 'zero packages' THEN 'client_returns_capture_format'
			WHEN 'malformed e-way bill' THEN 'client_returns_capture_format'
			WHEN 'lowercase vehicle' THEN 'client_returns_capture_format'
			WHEN 'e-way bill without a date' THEN 'client_returns_eway_pairing'
			WHEN 'validity before the e-way date' THEN 'client_returns_eway_pairing'
			WHEN 'overlong note' THEN 'client_returns_note_length'
			WHEN 'malformed consignor GSTIN' THEN 'client_returns_capture_format'
			WHEN 'malformed consignee GSTIN' THEN 'client_returns_capture_format'
			WHEN 'negative declared value' THEN 'client_returns_capture_format'
			WHEN 'declared value above the bound' THEN 'client_returns_capture_format'
			WHEN 'overlong brand document number' THEN 'client_returns_capture_format'
			WHEN 'validity without an e-way bill' THEN 'client_returns_eway_pairing'
			WHEN 'e-way date without a number' THEN 'client_returns_eway_pairing'
			WHEN 'overlong cancel reason' THEN 'client_returns_note_length'
			WHEN 'cancelled missing only its reason' THEN 'client_returns_cancel_pairing'
			WHEN 'zero line qty' THEN 'client_return_lines_qty_positive'
			WHEN 'picked above the line' THEN 'client_return_lines_picked_range'
			WHEN 'negative picked' THEN 'client_return_lines_picked_range'
			WHEN 'unknown reason' THEN 'client_return_lines_reason_check'
			WHEN 'line 0' THEN 'client_return_lines_line_no_positive'
			WHEN 'unknown source' THEN 'client_return_lines_source_check'
			WHEN 'returns line without its receipt line' THEN 'client_return_lines_source_shape'
			WHEN 'returns line without its RMA' THEN 'client_return_lines_source_shape'
			WHEN 'damaged line with a receipt line' THEN 'client_return_lines_source_shape'
			WHEN 'damaged line with a serial' THEN 'client_return_lines_source_shape'
			WHEN 'serial line above one unit' THEN 'client_return_lines_serial_unit'
			WHEN 'serial line picked half' THEN 'client_return_lines_serial_unit'
			WHEN 'duplicate arm' THEN 'client_return_lines_arm_unique'
			WHEN 'duplicate receipt line' THEN 'client_return_lines_receipt_line_unique'
			ELSE 'client_return_lines_line_no_unique'
		END;
		base := CASE
			WHEN probe IN ('picked without a device') THEN 'picked'
			WHEN probe IN ('cancelled with half a picker') THEN 'cancelled-picked'
			WHEN probe IN ('cancelled without a reason', 'overlong cancel reason', 'cancelled missing only its reason') THEN 'cancelled'
			WHEN probe IN ('unknown brand document type', 'dispatched without a package count', 'transporter without its snapshot',
				'dispatched with no carrier', 'zero packages', 'malformed e-way bill', 'lowercase vehicle',
				'e-way bill without a date', 'validity before the e-way date', 'malformed consignor GSTIN', 'malformed consignee GSTIN',
				'negative declared value', 'declared value above the bound',
				'overlong brand document number', 'validity without an e-way bill', 'e-way date without a number') THEN 'dispatched'
			ELSE 'draft'
		END;
		BEGIN
			r := gen_random_uuid();
			INSERT INTO "client_returns" ("id","tenant_id","client_id","warehouse_id","code","status","client_snapshot","consignee_address_kind","consignee_address","created_by")
			VALUES (r, t, c, w, 'RTC-R' || r::text, 'draft', '{}', 'return', '{}', u);
			IF base IN ('picked', 'cancelled-picked', 'dispatched') THEN
				UPDATE "client_returns" SET "status" = 'picked', "picked_by" = u, "picked_at" = now(), "picked_device_id" = d WHERE "id" = r;
			END IF;
			IF base = 'dispatched' THEN
				UPDATE "client_returns" SET "status" = 'dispatched', "dispatched_by" = u, "dispatched_at" = now(),
					"brand_document_type" = 'challan', "brand_document_number" = 'CH-1', "brand_document_date" = current_date,
					"package_count" = 1, "carrier_name" = 'BlueDart', "warehouse_snapshot" = '{}' WHERE "id" = r;
			END IF;
			IF base IN ('cancelled', 'cancelled-picked') THEN
				UPDATE "client_returns" SET "status" = 'cancelled', "cancelled_by" = u, "cancelled_at" = now(), "cancel_reason" = 'probe' WHERE "id" = r;
			END IF;
			-- A returns line for the line probes; the damaged-shaped probes get a damaged line.
			IF probe IN ('zero line qty', 'picked above the line', 'negative picked', 'unknown reason', 'line 0', 'unknown source',
				'returns line without its receipt line', 'returns line without its RMA', 'serial line above one unit', 'serial line picked half',
				'duplicate receipt line', 'duplicate line number') THEN
				INSERT INTO "client_return_lines" ("id","tenant_id","client_return_id","line_no","source","sku_id","batch_id","serial_id","return_receipt_line_id","rma_id","qty","picked_qty","reason_code","item_snapshot")
				VALUES (gen_random_uuid(), t, r, 1, 'returns', c, NULL, NULL, l, v, 2000, NULL, 'client-instruction', '{}');
			ELSIF probe IN ('damaged line with a receipt line', 'damaged line with a serial', 'duplicate arm') THEN
				INSERT INTO "client_return_lines" ("id","tenant_id","client_return_id","line_no","source","sku_id","batch_id","serial_id","return_receipt_line_id","rma_id","qty","picked_qty","reason_code","item_snapshot")
				VALUES (gen_random_uuid(), t, r, 1, 'damaged', c, NULL, NULL, NULL, NULL, 2000, NULL, 'damaged', '{}');
			END IF;
			CASE probe
				WHEN 'unknown status' THEN UPDATE "client_returns" SET "status" = 'lost' WHERE "id" = r;
				WHEN 'unknown address kind' THEN UPDATE "client_returns" SET "consignee_address_kind" = 'home' WHERE "id" = r;
				WHEN 'unknown brand document type' THEN UPDATE "client_returns" SET "brand_document_type" = 'debit_note' WHERE "id" = r;
				WHEN 'draft with a picker' THEN UPDATE "client_returns" SET "picked_by" = u, "picked_at" = now(), "picked_device_id" = d WHERE "id" = r;
				WHEN 'picked without a device' THEN UPDATE "client_returns" SET "picked_device_id" = NULL WHERE "id" = r;
				WHEN 'cancelled with half a picker' THEN UPDATE "client_returns" SET "picked_device_id" = NULL WHERE "id" = r;
				WHEN 'dispatched without a package count' THEN UPDATE "client_returns" SET "package_count" = NULL WHERE "id" = r;
				WHEN 'draft with a tracking ref' THEN UPDATE "client_returns" SET "tracking_ref" = 'AWB1' WHERE "id" = r;
				WHEN 'draft with a brand document' THEN UPDATE "client_returns" SET "brand_document_type" = 'challan' WHERE "id" = r;
				WHEN 'draft with a consignee GSTIN' THEN UPDATE "client_returns" SET "consignee_gstin" = '29ABCDE1234F1Z5' WHERE "id" = r;
				WHEN 'draft with a declared value' THEN UPDATE "client_returns" SET "declared_value_paise" = 100 WHERE "id" = r;
				WHEN 'transporter without its snapshot' THEN UPDATE "client_returns" SET "transporter_id" = v WHERE "id" = r;
				WHEN 'cancelled without a reason' THEN UPDATE "client_returns" SET "cancel_reason" = NULL, "cancelled_at" = NULL, "cancelled_by" = NULL WHERE "id" = r;
				WHEN 'draft with a canceller' THEN UPDATE "client_returns" SET "cancelled_by" = u, "cancelled_at" = now(), "cancel_reason" = 'x' WHERE "id" = r;
				WHEN 'dispatched with no carrier' THEN UPDATE "client_returns" SET "carrier_name" = NULL WHERE "id" = r;
				WHEN 'zero packages' THEN UPDATE "client_returns" SET "package_count" = 0 WHERE "id" = r;
				WHEN 'malformed e-way bill' THEN UPDATE "client_returns" SET "eway_bill_number" = '12345', "eway_bill_date" = current_date WHERE "id" = r;
				WHEN 'lowercase vehicle' THEN UPDATE "client_returns" SET "vehicle_number" = 'ka01ab1234' WHERE "id" = r;
				WHEN 'e-way bill without a date' THEN UPDATE "client_returns" SET "eway_bill_number" = '123456789012' WHERE "id" = r;
				WHEN 'validity before the e-way date' THEN UPDATE "client_returns" SET "eway_bill_number" = '123456789012', "eway_bill_date" = current_date, "eway_valid_until" = current_date - 1 WHERE "id" = r;
				WHEN 'overlong note' THEN UPDATE "client_returns" SET "note" = repeat('x', 501) WHERE "id" = r;
				WHEN 'malformed consignor GSTIN' THEN UPDATE "client_returns" SET "consignor_gstin" = '29abcde1234f1z5' WHERE "id" = r;
				WHEN 'malformed consignee GSTIN' THEN UPDATE "client_returns" SET "consignee_gstin" = '29ABCDE' WHERE "id" = r;
				WHEN 'negative declared value' THEN UPDATE "client_returns" SET "declared_value_paise" = -1 WHERE "id" = r;
				WHEN 'declared value above the bound' THEN UPDATE "client_returns" SET "declared_value_paise" = 1000000000001 WHERE "id" = r;
				WHEN 'overlong brand document number' THEN UPDATE "client_returns" SET "brand_document_number" = repeat('C', 41) WHERE "id" = r;
				WHEN 'validity without an e-way bill' THEN UPDATE "client_returns" SET "eway_valid_until" = current_date WHERE "id" = r;
				WHEN 'e-way date without a number' THEN UPDATE "client_returns" SET "eway_bill_date" = current_date WHERE "id" = r;
				WHEN 'overlong cancel reason' THEN UPDATE "client_returns" SET "cancel_reason" = repeat('x', 501) WHERE "id" = r;
				WHEN 'cancelled missing only its reason' THEN UPDATE "client_returns" SET "cancel_reason" = NULL WHERE "id" = r;
				WHEN 'zero line qty' THEN UPDATE "client_return_lines" SET "qty" = 0 WHERE "client_return_id" = r;
				WHEN 'picked above the line' THEN UPDATE "client_return_lines" SET "picked_qty" = 2001 WHERE "client_return_id" = r;
				WHEN 'negative picked' THEN UPDATE "client_return_lines" SET "picked_qty" = -1 WHERE "client_return_id" = r;
				WHEN 'unknown reason' THEN UPDATE "client_return_lines" SET "reason_code" = 'smelly' WHERE "client_return_id" = r;
				WHEN 'line 0' THEN UPDATE "client_return_lines" SET "line_no" = 0 WHERE "client_return_id" = r;
				WHEN 'unknown source' THEN UPDATE "client_return_lines" SET "source" = 'lost' WHERE "client_return_id" = r;
				WHEN 'returns line without its receipt line' THEN UPDATE "client_return_lines" SET "return_receipt_line_id" = NULL WHERE "client_return_id" = r;
				WHEN 'returns line without its RMA' THEN UPDATE "client_return_lines" SET "rma_id" = NULL WHERE "client_return_id" = r;
				WHEN 'damaged line with a receipt line' THEN UPDATE "client_return_lines" SET "return_receipt_line_id" = l WHERE "client_return_id" = r;
				WHEN 'damaged line with a serial' THEN UPDATE "client_return_lines" SET "serial_id" = u, "qty" = 1000 WHERE "client_return_id" = r;
				WHEN 'serial line above one unit' THEN UPDATE "client_return_lines" SET "serial_id" = u WHERE "client_return_id" = r;
				WHEN 'serial line picked half' THEN UPDATE "client_return_lines" SET "serial_id" = u, "qty" = 1000, "picked_qty" = 500 WHERE "client_return_id" = r;
				WHEN 'duplicate arm' THEN
					INSERT INTO "client_return_lines" ("id","tenant_id","client_return_id","line_no","source","sku_id","batch_id","serial_id","return_receipt_line_id","rma_id","qty","picked_qty","reason_code","item_snapshot")
					VALUES (gen_random_uuid(), t, r, 2, 'damaged', c, NULL, NULL, NULL, NULL, 1000, NULL, 'damaged', '{}');
				WHEN 'duplicate receipt line' THEN
					INSERT INTO "client_return_lines" ("id","tenant_id","client_return_id","line_no","source","sku_id","batch_id","serial_id","return_receipt_line_id","rma_id","qty","picked_qty","reason_code","item_snapshot")
					VALUES (gen_random_uuid(), t, r, 2, 'returns', v, NULL, NULL, l, v, 1000, NULL, 'client-instruction', '{}');
				WHEN 'duplicate line number' THEN
					INSERT INTO "client_return_lines" ("id","tenant_id","client_return_id","line_no","source","sku_id","batch_id","serial_id","return_receipt_line_id","rma_id","qty","picked_qty","reason_code","item_snapshot")
					VALUES (gen_random_uuid(), t, r, 1, 'damaged', v, NULL, NULL, NULL, NULL, 1000, NULL, 'damaged', '{}');
			END CASE;
			RAISE EXCEPTION USING ERRCODE = 'P0113', MESSAGE = 'probe accepted';
		EXCEPTION
			WHEN check_violation OR unique_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN SQLSTATE 'P0113' THEN
				refused_by := NULL;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0113: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "client_returns" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "client_return_lines" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0113: a probe row survived.';
	END IF;
END $$;
